public sealed record CreateOrderCommand(Guid CustomerId, decimal Total)
    : IRequest<Guid>;

public sealed class CreateOrderHandler(IOrderRepository repo)
    : IRequestHandler<CreateOrderCommand, Guid>
{
    public async Task<Guid> Handle(CreateOrderCommand request, CancellationToken token)
    {
        var order = Order.Create(request.CustomerId, request.Total);

        await repo.AddAsync(order, token);

        return order.Id;
    }
}

// Any number of handlers react to the same notification
public sealed class OrderCreatedHandler(IEmailSender email)
    : INotificationHandler<OrderCreated>
{
    public Task Handle(OrderCreated n, CancellationToken token) =>
        email.SendConfirmationAsync(n.OrderId, token);
}
